import { JxToolbarPlugin, JxToolbarPluginContext, JxToolbarItem } from 'jx-cell';

const SIZES: { label: string; value: string; style?: Record<string, string> }[] = [
  8, 9, 10, 11, 12, 14, 16, 18, 20, 22, 24, 28, 32, 36, 48, 72
].map(n => ({
  label: String(n),
  value: `${n}px`,
  style: { fontSize: `${n}px`, lineHeight: '1.4' },
}));

export class FontSizePlugin implements JxToolbarPlugin {
  readonly id = 'font-size';
  readonly label = 'Dimensione font';

  init(_ctx: JxToolbarPluginContext): void {}
  destroy(): void {}

  readonly items: JxToolbarItem[] = [
    {
      type: 'combo',
      k: 'fontSize',
      tooltip: 'Dimensione font',
      comboWidth: 68,
      comboPlaceholder: 'Dim.',
      options: SIZES,
    },
    { type: 'divisor' },
  ];
}
