import { Component, Input, OnInit } from '@angular/core';
import { JxCustomNestedHeaderBase, JxNestedHeaderCellContext } from 'jx-cell';

/**
 * Demo — Group Nested Header Component
 *
 * Mostra un'etichetta di gruppo con icona colorata e badge col numero di
 * colonne coperte. Dimostra l'uso di JxCustomNestedHeaderBase.
 *
 * Configurazione nel options:
 *   nestedHeaders: [[
 *     { title: 'Anagrafica', colspan: 1, component: GroupNestedHeaderComponent },
 *     { title: 'Calcoli',    colspan: 6, component: GroupNestedHeaderComponent },
 *     { title: 'Componenti', colspan: 9, component: GroupNestedHeaderComponent },
 *   ]]
 */
@Component({
  standalone: false,
  selector: 'app-group-nested-header',
  template: `
    <div class="gnh-root" [class.gnh-empty]="!title">
      <span *ngIf="icon" class="gnh-icon">{{ icon }}</span>
      <span class="gnh-title">{{ title || '&nbsp;' }}</span>
      <span *ngIf="colspan > 1" class="gnh-badge" [style.background]="badgeColor">{{ colspan }}</span>
    </div>
  `,
  styles: [`
    .gnh-root {
      display: flex;
      align-items: center;
      gap: 5px;
      padding: 0 4px;
      height: 100%;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: .4px;
      text-transform: uppercase;
      white-space: nowrap;
      overflow: hidden;
      color: inherit;
    }
    .gnh-empty { opacity: .25; }
    .gnh-icon { font-style: normal; }
    .gnh-title {
      flex: 1;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .gnh-badge {
      flex-shrink: 0;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-width: 18px;
      height: 18px;
      padding: 0 5px;
      border-radius: 9px;
      background: #6366f1;
      color: #fff;
      font-size: 10px;
      font-weight: 800;
      line-height: 1;
    }
  `]
})
export class GroupNestedHeaderComponent extends JxCustomNestedHeaderBase<any> implements OnInit {
  @Input() override context: JxNestedHeaderCellContext<any> = undefined!;

  icon = '';
  badgeColor = '#6366f1';

  private static readonly PALETTE = ['#6366f1', '#0ea5e9', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

  ngOnInit(): void {
    // Assegna un colore ciclico basato sull'indice della cella
    const idx = this.context?.cellIndex ?? 0;
    this.badgeColor = GroupNestedHeaderComponent.PALETTE[idx % GroupNestedHeaderComponent.PALETTE.length];

    // Assegna un'icona in base al nome del gruppo
    const t = (this.context?.title ?? '').toLowerCase();
    if (t.includes('calcol') || t.includes('calc'))    this.icon = '∑';
    else if (t.includes('anagrafi') || t.includes('info')) this.icon = '🪪';
    else if (t.includes('component') || t.includes('cell')) this.icon = '🔲';
    else if (t.includes('price') || t.includes('prezzo') || t.includes('€')) this.icon = '€';
    else if (t.includes('data') || t.includes('date'))  this.icon = '📅';
    else                                                 this.icon = '';
  }
}
