import { JxToolbarPlugin, JxToolbarPluginContext, JxToolbarItem } from 'jx-cell';

export class UndoRedoPlugin implements JxToolbarPlugin {
  readonly id = 'undo-redo';
  readonly label = 'Undo / Redo';

  private wb: JxToolbarPluginContext['workbook'] | null = null;

  init(ctx: JxToolbarPluginContext): void { this.wb = ctx.workbook; }
  destroy(): void { this.wb = null; }

  readonly items: JxToolbarItem[] = [
    {
      type: 'i', content: 'undo', tooltip: 'Annulla (Ctrl+Z)',
      onclick: () => { this.wb?.undo(); },
    },
    {
      type: 'i', content: 'redo', tooltip: 'Ripristina (Ctrl+Y)',
      onclick: () => { this.wb?.redo(); },
    },
    { type: 'divisor' },
  ];
}
