import { Component, Input } from '@angular/core';
import { JxCustomCellBase, JxCustomCellContext } from 'jx-cell';

interface DemoRow extends Record<string, any> {
  status?: string;
}

@Component({
  standalone: false,
  selector: 'app-status-badge-cell',
  template: `
    <button
      type="button"
      class="demo-status-cell"
      [class.demo-status-new]="value === 'Nuovo'"
      [class.demo-status-work]="value === 'In lavorazione'"
      [class.demo-status-ok]="value === 'Approvato'"
      [class.demo-status-ko]="value === 'Respinto'"
      [disabled]="!editable"
      (click)="cycle($event)"
      (keydown.enter)="cycle($event)"
      (keydown.space)="cycle($event)"
    >
      {{ value || 'Nuovo' }}
    </button>
  `
})
export class StatusBadgeCellComponent extends JxCustomCellBase<DemoRow> {
  @Input() override context: JxCustomCellContext<DemoRow> = undefined!;

  private readonly statuses = ['Nuovo', 'In lavorazione', 'Approvato', 'Respinto'];

  cycle(event?: Event): void {
    this.stopEvent(event);

    if (!this.editable) {
      return;
    }

    const currentIndex = this.statuses.indexOf(String(this.value ?? ''));
    const next = this.statuses[(currentIndex + 1) % this.statuses.length];
    this.commitValue(next);
  }

  override onActivate(event?: Event): void {
    this.cycle(event);
  }
}
