import { JxToolbarPlugin, JxToolbarPluginContext, JxToolbarItem } from 'jx-cell';

export class TextColorPlugin implements JxToolbarPlugin {
  readonly id = 'text-color';
  readonly label = 'Colore testo / sfondo';

  init(_ctx: JxToolbarPluginContext): void {}
  destroy(): void {}

  readonly items: JxToolbarItem[] = [
    { type: 'color', content: 'format_color_text',   tooltip: 'Colore testo',    k: 'color' },
    { type: 'color', content: 'format_color_fill',   tooltip: 'Colore sfondo',   k: 'backgroundColor' },
  ];
}
