import { JxToolbarPlugin, JxToolbarPluginContext, JxToolbarItem } from 'jx-cell';

type Wb = JxToolbarPluginContext['workbook'];

function applyToggleStyle(wb: Wb, prop: string, onValue: string, offValue: string): void {
  const sel = wb.getSelection();
  if (!sel) return;
  const style = wb.getCellStyle(sel.x1, sel.y1) as any;
  const current = style?.[prop] ?? '';
  const next = current === onValue ? offValue : onValue;
  const { x1, y1, x2, y2 } = sel;
  for (let y = Math.min(y1, y2); y <= Math.max(y1, y2); y++) {
    for (let x = Math.min(x1, x2); x <= Math.max(x1, x2); x++) {
      const name = `${wb.getColumnName(x)}${y + 1}`;
      wb.setCellStyle(name, { [prop]: next });
    }
  }
}

export class TextFormatPlugin implements JxToolbarPlugin {
  readonly id = 'text-format';
  readonly label = 'Formattazione testo';

  private wb: Wb | null = null;

  init(ctx: JxToolbarPluginContext): void { this.wb = ctx.workbook; }
  destroy(): void { this.wb = null; }

  readonly items: JxToolbarItem[] = [
    {
      type: 'i', content: 'format_bold', tooltip: 'Grassetto',
      onclick: () => { if (this.wb) applyToggleStyle(this.wb, 'fontWeight', 'bold', 'normal'); },
    },
    {
      type: 'i', content: 'format_italic', tooltip: 'Corsivo',
      onclick: () => { if (this.wb) applyToggleStyle(this.wb, 'fontStyle', 'italic', 'normal'); },
    },
    {
      type: 'i', content: 'format_underlined', tooltip: 'Sottolineato',
      onclick: () => { if (this.wb) applyToggleStyle(this.wb, 'textDecoration', 'underline', 'none'); },
    },
    {
      type: 'i', content: 'strikethrough_s', tooltip: 'Barrato',
      onclick: () => { if (this.wb) applyToggleStyle(this.wb, 'textDecoration', 'line-through', 'none'); },
    },
    { type: 'divisor' },
  ];
}
