import { NgModule } from '@angular/core';
import { BrowserModule } from '@angular/platform-browser';
import { FormsModule } from '@angular/forms';
import { JxCellModule } from 'jx-cell';
import { AppComponent } from './app.component';
import { StatusBadgeCellComponent } from './custom-cells/status-badge-cell.component';
import { CustomNumberCellComponent } from './custom-cells/custom-number-cell.component';
import { ColumnStatsHeaderComponent } from './custom-cells/column-stats-header.component';
import { PriorityCellComponent } from './custom-cells/priority-cell.component';
import { BudgetHeaderComponent } from './custom-cells/budget-header.component';
import { SumGaugeFooterComponent } from './custom-cells/sum-gauge-footer.component';
import { GroupNestedHeaderComponent } from './custom-cells/group-nested-header.component';
import { CollapsibleFooterToggleComponent } from './custom-cells/collapsible-footer-toggle.component';
import { PlLoadingHttpInterceptor, PlLoadingRegistryService, PlLoadingTraceModule } from 'pl-loading-trace';
import { HttpClientModule, HTTP_INTERCEPTORS } from '@angular/common/http';
@NgModule({
    providers: [PlLoadingRegistryService,
        {
      provide:  HTTP_INTERCEPTORS,
      useClass: PlLoadingHttpInterceptor,
      multi:    true,
    },

    ],
     declarations:[AppComponent, StatusBadgeCellComponent, CustomNumberCellComponent, ColumnStatsHeaderComponent, PriorityCellComponent, BudgetHeaderComponent, SumGaugeFooterComponent, GroupNestedHeaderComponent, CollapsibleFooterToggleComponent], imports:[BrowserModule, FormsModule, HttpClientModule, JxCellModule,
    PlLoadingTraceModule.forRoot({
      shared: { debounceMs: 200 },
      http:   { animationType: 'bar', modal: false },
      router: { animationType: 'bar' },
    }),
], bootstrap:[AppComponent] })
export class AppModule {}
