import { ChangeDetectorRef, Component, HostListener, Input, OnInit } from '@angular/core';
import {
  JxCancellableEvent, JxCellLifecycle, JxChangePayload,
  JxCustomCellBase, JxCustomCellContext,
} from 'jx-cell';

interface DemoRow extends Record<string, any> {
  customNumber?: number | string;
}

@Component({
  standalone: false,
  selector: 'app-custom-number-cell',
  template: `
    <input
      class="jx-num-ghost"
      type="text"
      inputmode="decimal"
      autocomplete="off"
      [attr.disabled]="editable ? null : ''"
      [value]="draft"
      (mousedown)="$event.stopPropagation()"
      (click)="$event.stopPropagation()"
      (focus)="onFocus()"
      (keydown)="onKey($event)"
      (input)="onInput($event)"
      (blur)="onBlur()"
    />
  `,
  styles: [`
    :host { display: block; }
    .jx-num-ghost {
      display: block;
      width: 100%;
      border: none; outline: none;
      background: transparent; color: inherit;
      font: inherit; line-height: normal; text-align: inherit;
      padding: 0; margin: 0;
      box-sizing: border-box;
      cursor: text;
    }
    .jx-num-ghost:disabled { cursor: default; }
  `],
})
export class CustomNumberCellComponent
  extends JxCustomCellBase<DemoRow>
  implements JxCellLifecycle, OnInit {

  @Input() override context: JxCustomCellContext<DemoRow> = undefined!;

  /** Valore visualizzato nell'input — stato locale indipendente dal workbook */
  draft = '';

  /** Valore al momento dell'apertura dell'editing — usato per il ripristino */
  private _holdValue: any = undefined;

  constructor(private cdr: ChangeDetectorRef) {
    super();
  }

  /** Blocca la propagazione di qualsiasi mousedown sull'host — impedisce che il
   *  grid chiami setSelection() e colori di blu la cella. */
  @HostListener('mousedown', ['$event'])
  onHostMouseDown(event: MouseEvent): void {
    event.stopPropagation();
  }

  ngOnInit(): void {
    this._holdValue = this.value;
    this.draft = this._fmt(this.value);
    this.wireLifecycle();
  }

  override onCellAttached(): void {
    this._holdValue = this.value;
    this.draft = this._fmt(this.value);
  }

  // ── Validazione ─────────────────────────────────────────────────────────────
  // Personalizza qui i criteri: devi restituire true se il valore è accettabile.
  private isValid(n: number): boolean {
    return Number.isFinite(n) && n >= 0 && n <= 9_999;
  }

  // ── Hook beforeChange (solo questa cella) ───────────────────────────────────
  jxOnBeforeChange(e: JxCancellableEvent<JxChangePayload>): void {
    // Ignora eventi provenienti da altre celle
    if (e.data.x !== this.x || e.data.y !== this.y) return;

    const raw = e.data.value;
    if (raw === '' || raw === null || raw === undefined) return; // stringa vuota sempre permessa

    const n = Number(raw);
    if (!Number.isNaN(n) && !this.isValid(n)) {
      e.cancel();
      // Ripristina il draft senza innescare change$ (il cancel lo blocca già)
      this.draft = this._fmt(this._holdValue);
      this.cdr.markForCheck();
    }
  }

  // ── Hook change (solo questa cella) ─────────────────────────────────────────
  jxOnChange(p: JxChangePayload): void {
    if (p.x !== this.x || p.y !== this.y) return;
    this._holdValue = p.value;
    this.draft = this._fmt(p.value);
    this.cdr.markForCheck();
  }

  // ── Gestione input ───────────────────────────────────────────────────────────
  onFocus(): void {
    this._holdValue = this.getValue() ?? this.value;
    this.draft = this._fmt(this._holdValue);
  }

  onInput(event: Event): void {
    event.stopPropagation();
    this.draft = (event.target as HTMLInputElement).value;
  }

  onKey(event: KeyboardEvent): void {
    // Ctrl+Z / Ctrl+Y: blocca undo/redo del grid mentre si digita nell'input.
    // Il browser gestisce nativamente l'undo del testo.
    if ((event.ctrlKey || event.metaKey) && ['z', 'Z', 'y', 'Y'].includes(event.key)) {
      event.stopPropagation();
      return;
    }

    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation(); // gestito qui, non da onInlineComponentKey
      this.draft = this._fmt(this._holdValue);
      this.cdr.markForCheck();
      this.focusCell();
      return;
    }

    if (event.key === 'Enter' || event.key === 'Tab') {
      // Commit del valore: preventDefault impedisce submit/tab nativo del browser.
      // NON stopPropagation: l'evento bolla a onInlineComponentKey che chiama
      // moveFrom() per spostare il focus sulla cella successiva/sottostante.
      event.preventDefault();
      this._commit();
      return;
    }

    // Tutti gli altri tasti: l'input li gestisce nativamente.
    // onInlineComponentKey li riceverà e farà stopPropagation senza altra azione.
  }

  onBlur(): void {
    this._commit();
  }

  // ── Commit ───────────────────────────────────────────────────────────────────
  private _commit(): void {
    if (!this.editable) return;
    const raw = this.draft.trim();
    if (raw === '') {
      this.commitValue('', false);
      return;
    }
    const n = Number(raw);
    this.commitValue(Number.isNaN(n) ? '' : n, false);
  }

  private _fmt(v: any): string {
    return v === null || v === undefined || v === '' ? '' : String(v);
  }
}
